const ART_URL=null;
const RDESC=[['高速','先手を取りたい','素早さ種族値が100以上'],['物理','物理技で攻めたい','攻撃が高く、特攻を大きく上回る'],['特殊','特殊技で攻めたい','特攻が高く、攻撃を大きく上回る'],['両刀','幅広く攻めたい','攻撃・特攻がどちらも高い'],['耐久','受けて粘りたい','HP・防御・特防の合計が高い']];
function roles(p){
  const [h,a,b,c,d,s]=p.s,out=[];
  if(s>=100)out.push('高速');
  if(a>=90&&c>=90&&Math.abs(a-c)<20)out.push('両刀');
  else if(a>=95&&a>=c+20)out.push('物理');
  else if(c>=95&&c>=a+20)out.push('特殊');
  if(h+b+d>=300)out.push('耐久');
  return out.length?out:['バランス'];
}
function describe(p){
  const d={高速:'素早さが高く、先手を取りやすい',物理:'物理技で攻める役割に向く',特殊:'特殊技で攻める役割に向く',両刀:'物理・特殊のどちらも火力がある',耐久:'体力と防御面が厚く、受けにも向く',バランス:'突出した能力はなく、技構成で役割が決まる'};
  return p.roles.map(r=>d[r]).join('。')+'。';
}
P.forEach(p=>{p.roles=roles(p);p.rank=p.s.map((v,i)=>1+P.filter(q=>q.s[i]>v).length)});
